import { useNavigate } from '@tanstack/react-router';

function ProductSearch() {
  const navigate = useNavigate();

  const goToPage = (page: number) => {
    // Type-safe navigation with separate to and search props
    navigate({
      to: '/products',
      search: (prev) => ({ ...prev, page }),
    });
  };

  return <button onClick={() => goToPage(2)}>Page 2</button>;
}

import { Link, useSearch } from '@tanstack/react-router';

function Pagination() {
  const { page } = useSearch({ from: '/products' });
  const nextPage = page + 1;

  return (
    // search can be a function that receives current search and returns updated search
    <Link
      to='/products'
      search={(prev) => ({ ...prev, page: nextPage })}
    >
      Next Page
    </Link>
  );
}

